<script lang="ts" module>import type {RxColor} from '$lib/registry/lib/color';export interface CodeProps{code:string;language?:string;filename?:string;color?:RxColor;variant?:'default'|'glow'|'gradient-border'|'minimal'|'terminal'|'window';theme?:'auto'|'light'|'dark';copyable?:boolean;lineNumbers?:boolean;highlightLines?:number[];wrap?:boolean;maxHeight?:string;onCopy?:(code:string)=>void}</script>
<script lang="ts">import {browser} from '$app/environment';import{onDestroy}from'svelte';import {styleColor} from '$lib/registry/lib/color';import type {CodeToken} from './highlight';let{code,language='text',filename,color,variant='default',theme='auto',copyable=false,lineNumbers=false,highlightLines=[],wrap=false,maxHeight,onCopy}:CodeProps=$props();let status=$state('');let tokens=$state<CodeToken[][]>();let statusTimer:ReturnType<typeof setTimeout>|undefined;const lines=$derived(code.split('\n'));$effect(()=>{const value=code,lang=language,mode=theme;if(!browser)return;let alive=true;import('./highlight').then(async({highlightCode})=>{const light=mode==='light'||(mode==='auto'&&matchMedia('(prefers-color-scheme: light)').matches);const result=await highlightCode(value,lang,light);if(alive)tokens=result});return()=>{alive=false}});async function copy(){if(statusTimer)clearTimeout(statusTimer);try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(code);else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('Copy failed');area.remove()}status='Copied';onCopy?.(code)}catch{status='Could not copy'}statusTimer=setTimeout(()=>{status='';statusTimer=undefined},1800)}onDestroy(()=>{if(statusTimer)clearTimeout(statusTimer)})</script>
<figure class="rx-code rx-code--{variant}" data-theme={theme} style={`${styleColor(color)??'--rx-color:var(--rx-primary)'};${maxHeight?`--rx-code-max:${maxHeight}`:''}`}>{#if filename||copyable||variant==='terminal'||variant==='window'}<figcaption>{#if variant==='window'}<span class="rx-code__lights" aria-hidden="true">● ● ●</span>{/if}<span>{filename??(variant==='terminal'?'Terminal':language)}</span>{#if copyable}<button type="button" onclick={copy}>Copy</button>{/if}</figcaption>{/if}<pre class:wrap aria-label={filename?`Code in ${filename}`:'Code sample'}><code>{#each (tokens??lines.map(line=>[{content:line}])) as line,i}<span class:highlight={highlightLines.includes(i+1)}><i aria-hidden="true">{lineNumbers?i+1:''}</i><b>{#each line as token}<em style:color={'color' in token?String(token.color):undefined}>{token.content}</em>{/each}</b>{#if i<(tokens?.length??lines.length)-1}{'\n'}{/if}</span>{/each}</code></pre><span class="rx-code__status" aria-live="polite">{status}</span></figure>
<style>.rx-code{position:relative;overflow:hidden;margin:0;border:1px solid rgb(var(--rx-text)/.12);border-radius:var(--rx-radius);background:rgb(var(--rx-dark));color:rgb(var(--rx-light))}.rx-code figcaption{display:flex;align-items:center;gap:.7rem;min-height:2.5rem;padding:0 .8rem;border-bottom:1px solid rgb(var(--rx-light)/.12);font-size:.78rem}.rx-code figcaption>span:not(.rx-code__lights){flex:1}.rx-code button{border:0;border-radius:.35rem;background:rgb(var(--rx-color)/.22);color:inherit;padding:.3rem .55rem;cursor:pointer}.rx-code pre{overflow:auto;max-height:var(--rx-code-max,none);margin:0;padding:1rem;font:500 .82rem/1.65 ui-monospace,SFMono-Regular,monospace;tab-size:2}.rx-code pre.wrap{white-space:pre-wrap;overflow-wrap:anywhere}.rx-code code>span{display:grid;grid-template-columns:auto 1fr;margin:0 -1rem;padding:0 1rem}.rx-code code>span.highlight{background:rgb(var(--rx-color)/.18)}.rx-code i{min-width:2.5rem;color:rgb(var(--rx-light)/.35);font-style:normal;user-select:none}.rx-code b,.rx-code em{font:inherit}.rx-code em{font-style:normal}.rx-code__status{position:absolute;clip:rect(0 0 0 0)}.rx-code--minimal{border:0;border-radius:0;background:transparent;color:rgb(var(--rx-text))}.rx-code--glow{box-shadow:0 0 1.5rem rgb(var(--rx-color)/.28)}.rx-code--gradient-border{border-color:transparent;background:linear-gradient(rgb(var(--rx-dark)),rgb(var(--rx-dark))) padding-box,linear-gradient(135deg,rgb(var(--rx-color)),hsl(from rgb(var(--rx-color)) calc(h + 45) s l)) border-box}.rx-code--terminal figcaption::before{content:'$';color:rgb(var(--rx-color));font-weight:800}.rx-code__lights{color:rgb(var(--rx-color));letter-spacing:.2rem}.rx-code[data-theme=light]{background:rgb(var(--rx-light));color:rgb(var(--rx-dark))}@media(prefers-color-scheme:light){.rx-code[data-theme=auto]{background:rgb(var(--rx-light));color:rgb(var(--rx-dark))}}@media(prefers-reduced-motion:reduce){.rx-code :global(*){transition:none!important}}</style>
